import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata, TurnUsage} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {ToolRegistry} from './tools/registry.js';

const promptBuilder = new PromptBuilder({identity: 'Usage test.'});
const session = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'go', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'c1', name: 't1', input: {}}};
const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason, usage});

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> { return {} as T; },
  };
};

const registry = (): ToolRegistry => {
  const tr = new ToolRegistry();
  tr.register({name: 't1', description: 't', inputSchema: {type: 'object'}}, async () => 'ok');
  return tr;
};

describe('Usage Aggregation', () => {
  it('sums usage across three rounds', async () => {
    let finalUsage: TurnUsage | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_s, _t, usage) => {
        finalUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 2, totalTokens: 12})],
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 20, outputTokens: 5, totalTokens: 25})],
        [{type: 'text', text: 'done'}, usageStop('end_turn', {inputTokens: 30, outputTokens: 8, totalTokens: 38})],
      ]),
      promptBuilder,
      registry(),
      {hooks}
    );

    await orchestrator.processMessage(session());

    expect(finalUsage).toEqual({
      inputTokens: 60,
      outputTokens: 15,
      totalTokens: 75,
    });
  });

  it('handles rounds with missing usage by not adding to the total', async () => {
    let finalUsage: TurnUsage | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_s, _t, usage) => {
        finalUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 2, totalTokens: 12})],
        [TOOL_CALL, usageStop('tool_use')], // Missing usage
        [{type: 'text', text: 'done'}, usageStop('end_turn', {inputTokens: 30, outputTokens: 8, totalTokens: 38})],
      ]),
      promptBuilder,
      registry(),
      {hooks}
    );

    await orchestrator.processMessage(session());

    expect(finalUsage).toEqual({
      inputTokens: 40,
      outputTokens: 10,
      totalTokens: 50,
    });
  });
});
